import{_ as l,l as i,o as e,c as n,v as o,p as s,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"图着色与启发","description":"","frontmatter":{"title":"图着色与启发","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/graph-coloring.md","filePath":"cs/graph-coloring.md","lastUpdated":1789023840000}'),p={name:"cs/graph-coloring.md"};function _(g,a,m,u,B,f){const t=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="图着色与启发" tabindex="-1">图着色与启发 <a class="header-anchor" href="#图着色与启发" aria-label="Permalink to &quot;图着色与启发&quot;">​</a></h1><div class="epigraph"><p>色数 $\\chi$ 是 NPC 优化；贪心按序用最小可行色，上界 $\\Delta+1$；Brooks 把完全图与奇环除外收到 $\\Delta$。</p><footer>—— 据 Brooks, On Colouring the Nodes of a Network, 1941；Garey and Johnson, 1979；CLRS 第 34 章整理</footer></div><p>上一课<a href="/cs/stable-marriage-algo">稳定婚姻</a>给顶点配对。本课给顶点<strong>颜色</strong>：相邻不同色，最少色数 \\(\\chi(G)\\)。判定 \\(k\\ge 3\\) 着色 NPC。不重写 GS。缺口是上界与启发式：贪心、 degeneracy 序、与精确指数算法点名。后课平面图有四色等特殊结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\chi(G)\\le \\Delta+1\\) 总成立：任意序贪心。Brooks：连通图若不是完全图或奇圈，则 \\(\\chi\\le\\Delta\\)。Mycielski 等造高色数低团数图，故 \\(\\chi\\) 不能只看团。缺口是算法：精确 3-着色 \\(O(c^n)\\) 可做；实用启发式按度降序或最小度消除序（ degeneracy）贪心，最坏仍可差。</p><p>不要把「色数等于 \\(\\Delta+1\\)」当常例：那只是上界。</p><h3 id="贪心序不是随便" tabindex="-1">贪心序不是随便 <a class="header-anchor" href="#贪心序不是随便" aria-label="Permalink to &quot;贪心序不是随便&quot;">​</a></h3><p>degeneracy \\(d\\)：反复删最小度点，过程中最大度 \\(\\le d\\)。则 \\(\\chi\\le d+1\\)。平面图 \\(d\\le 5\\)，六色容易；五色、四色更细。本课一般图只收到 degeneracy。区间图、弦图有完美消除序，本课点名：那些多项式。</p><p><span class="marginnote">Brooks 1941。着色 NPC 见 Garey–Johnson。CLRS 把 3-着色当 NPC 例子。后课平面分离与四色是平面算法课，不在本课证四色。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>精确：回溯 + 位掩码（\\(n\\) 小）或包含排斥。启发式：选序贪心；DSATUR（饱和度优先）常更好。下界：团数 \\(\\omega\\le\\chi\\)，以及 \\(\\chi\\ge n/\\alpha\\)。</p>',11)),(e(),s(c,null,{default:r(()=>[h(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%9B%BE%20G%22%5D%20--%3E%20GRD%5B%22%E5%BA%8F%20%2B%20%E8%B4%AA%E5%BF%83%20%CE%94%2B1%22%5D%0A%20%20G%20--%3E%20BR%5B%22Brooks%20%E2%89%A4%CE%94%22%5D%0A%20%20G%20--%3E%20HEX%5B%22%E7%B2%BE%E7%A1%AE%20%2F%20%E5%90%AF%E5%8F%91%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>补图着色是团覆盖，不混。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>贪心正确性平凡（局部最小色号可行）；近似比无常数保证（一般图）。与匹配：匹配是边 1-正则，边着色（Vizing）另论，\\(\\Delta\\) 或 \\(\\Delta+1\\)，本课点名不证。顶点着色的交换论证弱，故启发式为主。</p><p>寄存器分配把干涉图着色，启发式够用，本课不进编译实现。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证四色、不写 Hadwiger。不把列表着色、选择数展开。后课默认：一般图着色 NPC；贪心 \\(\\Delta+1\\)；特殊图类多项式。下一课平面图算法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\chi\\) 判定难；贪心 \\(\\Delta+1\\)，Brooks 常 \\(\\Delta\\)。</li><li>degeneracy 给出更紧的贪心上界。</li><li>启发不是近似比定理。</li><li>出处：Brooks, 1941；Garey and Johnson, 1979。</li></ul>',8))])}const D=l(p,[["render",_]]);export{E as __pageData,D as default};
